window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-e0362b9ad19a46d6"]={"versions": [{"id": "FIG-e0362b9ad19a46d6", "releases": ["R19-11", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des Kontrollflusses innerhalb der Funktion <code>E2E_P11Forward()</code> im AUTOSAR E2E-Protokoll (Profile 11). Das Diagramm detailliert den Teilschritt „Verify inputs of the forward function“ zur formalen Eingangsüberprüfung vor der eigentlichen Forward-Verarbeitung.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Kontext / Funktion</strong>: <code>E2E_P11Forward()</code>\n</li><li><strong>Eingangsparameter</strong>:\n<ul class=\"fig-list\"><li><code>Config</code>: Zeiger auf die E2E-Konfigurationsstruktur (enthält u. a. <code>DataLength</code>)\n</li><li><code>State</code>: Zeiger auf den E2E-Zustandsspeicher\n</li><li><code>Data</code>: Zeiger auf das Nutzdatenarray\n</li><li><code>Length</code>: Datenlänge in Bytes\n</li><li><code>ForwardStatus</code>: Statusübergabewert (Enum / Statuswert, verglichen mit <code>E2E_P_NONEWDATA</code>)\n</li></ul>\n</li><li><strong>Entscheidungsknoten (Decisions)</strong>:\n<ul class=\"fig-list\"><li>Nullzeiger-Prüfung der Zeiger-Argumente (<code>Config</code>, <code>State</code>, <code>Data</code>, <code>ForwardStatus</code>)\n</li><li>Konsistenzprüfung der Datenlänge (<code>Length == Config-&gt;DataLength/8</code>) und des Status (<code>ForwardStatus != E2E_P_NONEWDATA</code>)\n</li></ul>\n</li><li><strong>Aktivitäts-Endzustände</strong>:\n<ul class=\"fig-list\"><li><code>no input</code>: Nullzeiger erkannt (führt im umgebenden Ablauf zu <code>E2E_E_INPUTERR_NULL</code>)\n</li><li><code>wrong input</code>: Ungültige Länge oder Status <code>E2E_P_NONEWDATA</code> (führt zu <code>E2E_E_INPUTERR_WRONG</code>)\n</li><li><code>input ok</code>: Alle Parameter gültig; Fortsetzung der Forward-Verarbeitung\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Start</strong>: Eintritt über den initialen Pseudozustand in <code>E2E_P11Forward()</code>.\n</li><li><strong>Erste Verzweigung (Nullzeiger-Check)</strong>:\n<ul class=\"fig-list\"><li>Bedingung: <code>(Config != NULL) &amp;&amp; (State != NULL) &amp;&amp; (Data != NULL) &amp;&amp; (ForwardStatus != NULL)</code>\n</li><li>Pfad <code>[FALSE]</code>: Verzweigung zum Endzustand <code>no input</code>.\n</li><li>Pfad <code>[TRUE]</code>: Übergang zur zweiten Verzweigung.\n</li></ul>\n</li><li><strong>Zweite Verzweigung (Konsistenz-Check)</strong>:\n<ul class=\"fig-list\"><li>Bedingung: <code>Length == Config-&gt;DataLength/8 &amp;&amp; (ForwardStatus != E2E_P_NONEWDATA)</code>\n</li><li>Pfad <code>[FALSE]</code>: Verzweigung zum Endzustand <code>wrong input</code>.\n</li><li>Pfad <code>[TRUE]</code>: Verzweigung zum Endzustand <code>input ok</code>.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Normative Bindung</strong>: Verbindliche Eingangsprüfung für E2E Profile 11 Forwarding gemäß [PRS_E2E_00631] / RS_E2E_08539.\n</li><li><strong>Implementierungsvorschrift</strong>: Zeiger müssen vor Zugriffen strikt auf <code>NULL</code> geprüft werden, um Speicherzugriffsfehler abzufangen. Bei <code>no input</code> ist der Rückgabewert <code>E2E_E_INPUTERR_NULL</code> zu setzen.\n</li><li><strong>Längenberechnung</strong>: <code>Config-&gt;DataLength</code> ist in Bits spezifiziert; der Vergleich mit <code>Length</code> erfordert die Division durch 8 (<code>DataLength / 8</code>).\n</li><li><strong>Statusbehandlung</strong>: Wenn <code>ForwardStatus == E2E_P_NONEWDATA</code>, darf keine Vorwärtsverarbeitung erfolgen; es resultiert <code>E2E_E_INPUTERR_WRONG</code>.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-c155a1638d4b218a", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des Kontrollflusses innerhalb der Funktion <code>E2E_P11Forward()</code> im AUTOSAR E2E-Protokoll (Profile 11). Das Diagramm detailliert den Teilschritt „Verify inputs of the forward function“ zur formalen Eingangsüberprüfung vor der eigentlichen Forward-Verarbeitung.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Kontext / Funktion</strong>: <code>E2E_P11Forward()</code>\n</li><li><strong>Eingangsparameter</strong>:\n<ul class=\"fig-list\"><li><code>Config</code>: Zeiger auf die E2E-Konfigurationsstruktur (enthält u. a. <code>DataLength</code>)\n</li><li><code>State</code>: Zeiger auf den E2E-Zustandsspeicher\n</li><li><code>Data</code>: Zeiger auf das Nutzdatenarray\n</li><li><code>Length</code>: Datenlänge in Bytes\n</li><li><code>ForwardStatus</code>: Statusübergabewert (Enum / Statuswert, verglichen mit <code>E2E_P_NONEWDATA</code>)\n</li></ul>\n</li><li><strong>Entscheidungsknoten (Decisions)</strong>:\n<ul class=\"fig-list\"><li>Nullzeiger-Prüfung der Zeiger-Argumente (<code>Config</code>, <code>State</code>, <code>Data</code>, <code>ForwardStatus</code>)\n</li><li>Konsistenzprüfung der Datenlänge (<code>Length == Config-&gt;DataLength/8</code>) und des Status (<code>ForwardStatus != E2E_P_NONEWDATA</code>)\n</li></ul>\n</li><li><strong>Aktivitäts-Endzustände</strong>:\n<ul class=\"fig-list\"><li><code>no input</code>: Nullzeiger erkannt (führt im umgebenden Ablauf zu <code>E2E_E_INPUTERR_NULL</code>)\n</li><li><code>wrong input</code>: Ungültige Länge oder Status <code>E2E_P_NONEWDATA</code> (führt zu <code>E2E_E_INPUTERR_WRONG</code>)\n</li><li><code>input ok</code>: Alle Parameter gültig; Fortsetzung der Forward-Verarbeitung\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Start</strong>: Eintritt über den initialen Pseudozustand in <code>E2E_P11Forward()</code>.\n</li><li><strong>Erste Verzweigung (Nullzeiger-Check)</strong>:\n<ul class=\"fig-list\"><li>Bedingung: <code>(Config != NULL) &amp;&amp; (State != NULL) &amp;&amp; (Data != NULL) &amp;&amp; (ForwardStatus != NULL)</code>\n</li><li>Pfad <code>[FALSE]</code>: Verzweigung zum Endzustand <code>no input</code>.\n</li><li>Pfad <code>[TRUE]</code>: Übergang zur zweiten Verzweigung.\n</li></ul>\n</li><li><strong>Zweite Verzweigung (Konsistenz-Check)</strong>:\n<ul class=\"fig-list\"><li>Bedingung: <code>Length == Config-&gt;DataLength/8 &amp;&amp; (ForwardStatus != E2E_P_NONEWDATA)</code>\n</li><li>Pfad <code>[FALSE]</code>: Verzweigung zum Endzustand <code>wrong input</code>.\n</li><li>Pfad <code>[TRUE]</code>: Verzweigung zum Endzustand <code>input ok</code>.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Normative Bindung</strong>: Verbindliche Eingangsprüfung für E2E Profile 11 Forwarding gemäß [PRS_E2E_00631] / RS_E2E_08539.\n</li><li><strong>Implementierungsvorschrift</strong>: Zeiger müssen vor Zugriffen strikt auf <code>NULL</code> geprüft werden, um Speicherzugriffsfehler abzufangen. Bei <code>no input</code> ist der Rückgabewert <code>E2E_E_INPUTERR_NULL</code> zu setzen.\n</li><li><strong>Längenberechnung</strong>: <code>Config-&gt;DataLength</code> ist in Bits spezifiziert; der Vergleich mit <code>Length</code> erfordert die Division durch 8 (<code>DataLength / 8</code>).\n</li><li><strong>Statusbehandlung</strong>: Wenn <code>ForwardStatus == E2E_P_NONEWDATA</code>, darf keine Vorwärtsverarbeitung erfolgen; es resultiert <code>E2E_E_INPUTERR_WRONG</code>.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-e0362b9ad19a46d6", "to": "FIG-c155a1638d4b218a", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
